import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:freezed_annotation/freezed_annotation.dart';

part 'test_firestore_dto.g.dart';

@JsonSerializable()
class TestFirestoreDto {
  const TestFirestoreDto({required this.name, required this.createdAt});

  // Add all table fields, except the ID which is generated by Firestore and is redundant in the DTO.
  final String name;
  final DateTime createdAt;

  // Factory constructor to create a TestFirestoreDto from a JSON map.
  factory TestFirestoreDto.fromJson(Map<String, dynamic> json) =>
      _$TestFirestoreDtoFromJson(json);

  // Converts this DTO to a JSON map for Firestore storage.
  Map<String, dynamic> toJson() => _$TestFirestoreDtoToJson(this);

  // Factory constructor to create a TestFirestoreDto from Firestore document data.
  factory TestFirestoreDto.fromFirestore(Map<String, dynamic> data) {
    return TestFirestoreDto(
      name: data['name'] ?? '',
      createdAt: (data['createdAt'] as Timestamp?)?.toDate() ?? DateTime.now(),
    );
  }
}
